CLIENT_FIELDS = [
    ("name", "Имя"),
    ("phone", "Телефон"),
    ("telegram", "Telegram"),
    ("prepayment", "Предоплата"),
    ("wishes", "Заметка"),
]


def client_of(card):
    """Карточка покупателя, привязанная к авто."""
    cid = card.get("client_id")
    if not cid:
        return None
    try:
        return db.get_card("clients", int(cid))
    except Exception:
        return None


async def client_screen(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await _v168_ack(q,)
    drop_wait(context)
    cid = int(q.data.split(":")[-1])
    card = card_of(cid)
    klient = client_of(card)
    nomer = card.get("auto_number") or "#%d" % cid

    if not klient:
        try:
            client_id = db.create_card("clients", {"car_interest": nomer},
                                       q.from_user.id)
            set_field(cid, "client_id", client_id, q.from_user.id)
        except Exception as e:
            log.warning("Не создал карточку клиента: %s", e)
            raise ApplicationHandlerStop
        card = card_of(cid)
        klient = client_of(card)

    lines = ["<b>Покупатель</b>",
             "%s · %s" % (nomer, " ".join(str(x) for x in (card.get("brand"),
                                                           card.get("model")) if x)),
             ""]
    for key, label in CLIENT_FIELDS:
        lines.append("%s: %s" % (label, klient.get(key) or "—"))
    lines.append("")
    lines.append("<i>Эти данные видите и правите вы и менеджер. "
                 "Когда клиент оформляет авто сам, они попадают сюда же.</i>")

    rows, buf = [], []
    for key, label in CLIENT_FIELDS:
        buf.append(InlineKeyboardButton(label, callback_data="car_setc:%d:%s" % (cid, key)))
        if len(buf) == 2:
            rows.append(buf)
            buf = []
    if buf:
        rows.append(buf)
    rows.append([InlineKeyboardButton("Отвязать покупателя",
                                      callback_data="car_unclient:%d" % cid)])
    rows.append([InlineKeyboardButton("← Вернуться к карточке",
                                      callback_data="car_open:%d" % cid)])
    await q.message.reply_text("\n".join(lines), parse_mode="HTML",
                               reply_markup=InlineKeyboardMarkup(rows))
    raise ApplicationHandlerStop


async def client_ask(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await _v168_ack(q,)
    _, cid, field = q.data.split(":")
    card = card_of(cid)
    klient = client_of(card) or {}
    label = dict(CLIENT_FIELDS).get(field, field)
    _ua_wait_text(context, {"card_id": int(cid), "field": field,
                                     "client": True})
    await q.message.reply_text(
        "<b>%s</b>\nСейчас: %s\n\nПришлите новое значение."
        % (label, klient.get(field) or "—"),
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("← Отмена", callback_data="car_client:%s" % cid)]]))
    raise ApplicationHandlerStop


