        text = ("<b>Заявки из бота</b>\n\n"
                "Пока ни одной. Появятся здесь сами, как только клиент "
                "оставит заявку в каталоге или закажет подбор.")
    else:
        L = ["<b>Заявки из бота</b> — всего %d" % len(lidy), ""]
        for l in lidy[:15]:
