def chit(put):
    try:
        with io.open(put, "r", encoding="utf-8", errors="replace") as f:
            return f.read()
    except Exception:
        return None
def pis(put, t):
    vrem = put + ".tmp"
    with io.open(vrem, "w", encoding="utf-8") as f:
        f.write(t)
    os.replace(vrem, put)
def sha(put):
    h = hashlib.sha256()
    try:
        with io.open(put, "rb") as f:
            while True:
                b = f.read(524288)
                if not b:
                    break
                h.update(b)
        return h.hexdigest()
    except Exception:
        return ""

