# -*- coding: utf-8 -*-
"""
UA ART * ЦИФРЫ КАТАЛОГА * метка UA-CIFRY-V1

Ставится в /home/Carix, запускается кнопкой Run this file.

Что чинит:
  1) чипы фильтра каталога ("Все * 5", "В Киеве * 1" и т.д.) — их числа
     вписаны В ТЕКСТ страницы пакетом линии и никогда не пересчитывались;
  2) двойные карточки одной и той же машины в каталоге — из-за них
     строка "Показано: N" больше, чем число машин;
  3) ставит сторож цифр — маленький скрипт в начало katalog.html, который
     при КАЖДОМ открытии страницы сам пересчитывает числа по фактическим
     карточкам, прячет дубли и правит строку "Показано".

Что НЕ трогает: crm.db (только чтение), бот, фото, видео, ua.css,
index.html, страницы машин, предпросмотр. Ничего не удаляет.

Идемпотентен: повторный запуск снимает старый сторож и ставит свежий.
"""

import os
import re
import sqlite3
import shutil
import time
import random

DOM = "/home/Carix"
BAZA = os.path.join(DOM, "crm.db")
PAPKI = [os.path.join(DOM, "video"), os.path.join(DOM, "site")]
METKA = "UA-CIFRY-V1"
MOMENT = time.strftime("%Y%m%d_%H%M")
REZERV = os.path.join(DOM, "rezerv_cifry_" + MOMENT)

ETAPY = ["kiev", "georgia", "sea", "korea"]

SINONIMY = {
    "kiev": "kiev", "ua_arrived": "kiev", "ua": "kiev", "kyiv": "kiev",
    "ukraine": "kiev", "rastamozhka": "kiev", "arrived": "kiev",
    "georgia": "georgia", "ge_waiting": "georgia", "ge": "georgia",
    "gruzia": "georgia", "gruziya": "georgia",
    "sea": "sea", "sea_loaded": "sea", "more": "sea", "ship": "sea",
    "v_more": "sea", "loaded": "sea",
    "korea": "korea", "kr_bought": "korea", "kr": "korea",
    "korea_stock": "korea", "bought": "korea", "kr_stock": "korea",
}

PODPISI = {
    "vse":     ["Все", "Всi", "Всі", "Усі", "Усi"],
    "kiev":    ["В Киеве", "У Києві", "У Києвi", "Киев", "Київ"],
    "georgia": ["В Грузии", "У Грузії", "У Грузii", "Грузия", "Грузія"],
    "sea":     ["В море", "У морі", "У морi", "В пути", "У дорозі"],
    "korea":   ["В Корее", "У Кореї", "У Кореi", "Корея", "Корея"],
}

otchet = []


def skazat(s):
    print(s)
    otchet.append(s)


# ---------------------------------------------------------------- база

def etap_klyuch(znachenie):
    if not znachenie:
        return ""
    t = str(znachenie).strip().lower()
    if t in SINONIMY:
        return SINONIMY[t]
    for kus, klyuch in SINONIMY.items():
        if kus and kus in t:
            return klyuch
    if "кие" in t or "київ" in t or "укра" in t:
        return "kiev"
    if "груз" in t:
        return "georgia"
    if "мор" in t:
        return "sea"
    if "коре" in t:
        return "korea"
    return ""


def chitat_bazu():
    """Возвращает {код: этап} по crm.db. Только чтение."""
    itog = {}
    if not os.path.exists(BAZA):
        skazat("!! crm.db не найден по пути " + BAZA)
        return itog
    try:
        soed = sqlite3.connect("file:" + BAZA + "?mode=ro", uri=True, timeout=10)
    except Exception as osh:
        skazat("!! база не открылась: " + str(osh))
        return itog
    try:
        kursor = soed.cursor()
        kursor.execute("SELECT name FROM sqlite_master WHERE type='table'")
        tablicy = [r[0] for r in kursor.fetchall()]
        luchshaya = None
        for tabl in tablicy:
            try:
                kursor.execute("PRAGMA table_info(%s)" % tabl)
                kolonki = [r[1] for r in kursor.fetchall()]
            except Exception:
                continue
            kod_kol = None
            for k in kolonki:
                if k.lower() in ("auto_number", "kod", "code", "number", "nomer"):
                    kod_kol = k
                    break
            if not kod_kol:
                continue
            try:
                kursor.execute("SELECT %s FROM %s LIMIT 200" % (kod_kol, tabl))
                obrazcy = [str(r[0] or "") for r in kursor.fetchall()]
            except Exception:
                continue
            if not any(re.match(r"^UA-\d{3,5}$", o.strip()) for o in obrazcy):
                continue
            etap_kol = None
            for k in kolonki:
                if k.lower() in ("stage", "etap", "stage_key"):
                    etap_kol = k
                    break
            if not etap_kol:
                for k in kolonki:
                    if k.lower() in ("status", "state"):
                        etap_kol = k
                        break
            luchshaya = (tabl, kod_kol, etap_kol, kolonki)
            break
        if not luchshaya:
            skazat("!! в crm.db не нашлась таблица с кодами UA-XXXX")
            return itog
        tabl, kod_kol, etap_kol, kolonki = luchshaya
        skazat("База: таблица %s, код в колонке %s, этап в колонке %s"
               % (tabl, kod_kol, etap_kol or "нет"))
        zapas = None
        for k in kolonki:
            if k.lower() in ("status", "state") and k != etap_kol:
                zapas = k
                break
        polya = [kod_kol] + [k for k in (etap_kol, zapas) if k]
        kursor.execute("SELECT %s FROM %s" % (", ".join(polya), tabl))
        for stroka in kursor.fetchall():
            kod = str(stroka[0] or "").strip().upper()
            if not re.match(r"^UA-\d{3,5}$", kod):
                continue
            klyuch = ""
            for znach in stroka[1:]:
                klyuch = etap_klyuch(znach)
                if klyuch:
                    break
            itog[kod] = klyuch
    except Exception as osh:
        skazat("!! ошибка чтения базы: " + str(osh))
    finally:
        try:
            soed.close()
        except Exception:
            pass
    return itog


# ---------------------------------------------------------------- страница

SSYLKA = re.compile(r'href=["\']([^"\']*?(UA-\d{3,5})[^"\']*?)["\']', re.I)


def kody_na_stranice(tekst):
    """Уникальные коды машин в порядке появления + сколько ссылок на каждый."""
    poryadok = []
    skolko = {}
    for celaya, kod in SSYLKA.findall(tekst):
        if "-diag" in celaya.lower():
            continue
        kod = kod.upper()
        skolko[kod] = skolko.get(kod, 0) + 1
        if kod not in poryadok:
            poryadok.append(kod)
    return poryadok, skolko


def pochinit_podpisi(tekst, cifry):
    """Правит числа в чипах вида 'Все * 5'. Возвращает текст и список замен."""
    zameny = []
    for klyuch, varianty in PODPISI.items():
        nado = cifry.get(klyuch)
        if nado is None:
            continue
        for podpis in varianty:
            shablon = re.compile(
                r'(' + re.escape(podpis) + r'\s*(?:&middot;|&#183;|[\u00b7\u2022\u00b7])\s*)(\d+)')

            def zamena(m, nado=nado, podpis=podpis):
                if m.group(2) != str(nado):
                    zameny.append("%s: %s -> %s" % (podpis, m.group(2), nado))
                return m.group(1) + str(nado)

            tekst = shablon.sub(zamena, tekst)
    return tekst, zameny


STOROZH = r"""<script id="ua-cifry-storozh">/* UA-CIFRY-V1 */
(function(){
try{
var PODPISI={
 vse:["Все","Всi","Всі","Усі","Усi"],
 kiev:["В Киеве","У Києві","У Києвi","Киев","Київ"],
 georgia:["В Грузии","У Грузії","У Грузii","Грузия","Грузія"],
 sea:["В море","У морі","У морi","В пути","У дорозі"],
 korea:["В Корее","У Кореї","У Кореi","Корея"]};
var ETAPY=["kiev","georgia","sea","korea"];
function etapPoTekstu(t){
 t=(t||"").toLowerCase();
 if(t.indexOf("кие")>=0||t.indexOf("київ")>=0||t.indexOf("києв")>=0)return "kiev";
 if(t.indexOf("груз")>=0)return "georgia";
 if(t.indexOf("мор")>=0)return "sea";
 if(t.indexOf("коре")>=0)return "korea";
 return "";
}
function normEtap(z){
 z=(z||"").toLowerCase();
 if(z.indexOf("kiev")>=0||z.indexOf("ua_")>=0||z.indexOf("ukr")>=0)return "kiev";
 if(z.indexOf("georg")>=0||z.indexOf("ge_")>=0||z.indexOf("gruz")>=0)return "georgia";
 if(z.indexOf("sea")>=0||z.indexOf("more")>=0)return "sea";
 if(z.indexOf("kore")>=0||z.indexOf("kr_")>=0)return "korea";
 return etapPoTekstu(z);
}
function sobratKartochki(){
 var spisok=[],bylo=[];
 var ssylki=document.querySelectorAll('a[href*="UA-"]');
 for(var i=0;i<ssylki.length;i++){
  var h=ssylki[i].getAttribute("href")||"";
  if(h.toLowerCase().indexOf("-diag")>=0)continue;
  var m=h.match(/UA-\d{3,5}/);
  if(!m)continue;
  var kart=null;
  if(ssylki[i].closest)kart=ssylki[i].closest("[data-stage]");
  if(!kart){
   var p=ssylki[i],shag=0;
   while(p&&p.parentElement&&shag<6){
    p=p.parentElement;
    var kl=(p.className&&p.className.baseVal!==undefined)?p.className.baseVal:(p.className||"");
    if(typeof kl==="string"&&/kart|card|auto|avto|tile|item|mash/i.test(kl)){kart=p;break;}
    shag++;
   }
  }
  if(!kart)kart=ssylki[i].parentElement;
  if(!kart)continue;
  if(bylo.indexOf(kart)>=0)continue;
  bylo.push(kart);
  kart.setAttribute("data-ua-kod",m[0]);
  spisok.push(kart);
 }
 return spisok;
}
function schitat(){
 var karty=sobratKartochki();
 var vidano={},cifry={vse:0,kiev:0,georgia:0,sea:0,korea:0},dubley=0;
 for(var i=0;i<karty.length;i++){
  var k=karty[i],kod=k.getAttribute("data-ua-kod");
  if(vidano[kod]){k.setAttribute("data-ua-dubl","1");k.style.display="none";dubley++;continue;}
  vidano[kod]=1;
  k.removeAttribute("data-ua-dubl");
  var et=normEtap(k.getAttribute("data-stage")||"");
  if(!et)et=etapPoTekstu(k.textContent||"");
  cifry.vse++;
  if(et&&cifry[et]!==undefined)cifry[et]++;
 }
 cifry.dubley=dubley;
 cifry.karty=karty;
 return cifry;
}
function listya(){
 var vse=document.querySelectorAll("a,span,button,div,li,p,em,b,strong,small");
 var res=[];
 for(var i=0;i<vse.length;i++){
  var e=vse[i];
  if(e.children&&e.children.length>0)continue;
  var t=e.textContent||"";
  if(t.length>40)continue;
  res.push(e);
 }
 return res;
}
function vpisat(cifry){
 var lis=listya(),i,j,k;
 for(i=0;i<lis.length;i++){
  var e=lis[i],t=e.textContent||"";
  for(k in PODPISI){
   if(!PODPISI.hasOwnProperty(k))continue;
   if(cifry[k]===undefined)continue;
   var spisok=PODPISI[k];
   for(j=0;j<spisok.length;j++){
    var re1=new RegExp("^\\s*"+spisok[j].replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+"\\s*[\u00b7\u2022:]\\s*\\d+\\s*$");
    if(re1.test(t)){
     var novoe=spisok[j]+" \u00b7 "+cifry[k];
     if(t.replace(/\s+/g," ").trim()!==novoe)e.textContent=novoe;
     j=spisok.length;k="";break;
    }
   }
   if(k==="")break;
  }
 }
}
function vidimyh(){
 var karty=sobratKartochki(),vidano={},n=0;
 for(var i=0;i<karty.length;i++){
  var k=karty[i],kod=k.getAttribute("data-ua-kod");
  if(k.getAttribute("data-ua-dubl")==="1")continue;
  if(vidano[kod])continue;
  vidano[kod]=1;
  var st=window.getComputedStyle?window.getComputedStyle(k):null;
  if(st&&(st.display==="none"||st.visibility==="hidden"))continue;
  n++;
 }
 return n;
}
function pokazano(){
 var n=vidimyh(),lis=listya();
 for(var i=0;i<lis.length;i++){
  var e=lis[i],t=(e.textContent||"").replace(/\s+/g," ").trim();
  if(/^(Показано|Показанo|Показано:|Показуємо|Показано авто)\s*:?\s*\d+$/.test(t)){
   var novoe=t.replace(/\d+/,String(n));
   if(t!==novoe)e.textContent=novoe;
  }
 }
}
function krug(){
 try{var c=schitat();vpisat(c);pokazano();}catch(e){}
}
function zapusk(){
 krug();
 setTimeout(krug,400);
 setTimeout(pokazano,900);
 document.addEventListener("click",function(){setTimeout(krug,80);setTimeout(krug,400);},true);
 window.addEventListener("hashchange",function(){setTimeout(krug,80);});
 window.addEventListener("popstate",function(){setTimeout(krug,80);});
}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",zapusk);}else{zapusk();}
}catch(e){}
})();
</script>
"""

SNYAT = re.compile(r'<script id="ua-cifry-storozh">.*?</script>\s*',
                   re.S | re.I)


def postavit_storozh(tekst):
    tekst = SNYAT.sub("", tekst)
    nizhe = re.search(r"<head[^>]*>", tekst, re.I)
    if nizhe:
        mesto = nizhe.end()
        return tekst[:mesto] + "\n" + STOROZH + tekst[mesto:]
    return STOROZH + tekst


# ---------------------------------------------------------------- работа

def main():
    skazat("=" * 52)
    skazat("UA ART * ЦИФРЫ КАТАЛОГА * " + METKA)
    skazat("=" * 52)

    baza = chitat_bazu()
    skazat("Машин в базе: %d" % len(baza))
    po_etapam_bazy = {}
    for kod, et in baza.items():
        po_etapam_bazy[et or "?"] = po_etapam_bazy.get(et or "?", 0) + 1
    skazat("По базе: " + ", ".join(
        "%s %d" % (k, v) for k, v in sorted(po_etapam_bazy.items())))

    os.makedirs(REZERV, exist_ok=True)
    tronuto = 0
    fantomy_vse = []
    dubli_vse = []

    for papka in PAPKI:
        put = os.path.join(papka, "katalog.html")
        if not os.path.exists(put):
            skazat("- нет файла " + put)
            continue
        skazat("")
        skazat("--- " + put)
        try:
            with open(put, "r", encoding="utf-8", errors="replace") as f:
                tekst = f.read()
        except Exception as osh:
            skazat("!! не прочитать: " + str(osh))
            continue

        kopiya = os.path.join(REZERV, papka.rstrip("/").split("/")[-1] + "_katalog.html")
        try:
            shutil.copy2(put, kopiya)
            skazat("резервная копия: " + kopiya)
        except Exception as osh:
            skazat("!! резервная копия не сделана, файл НЕ меняю: " + str(osh))
            continue

        poryadok, skolko = kody_na_stranice(tekst)
        skazat("машин на странице (по ссылкам): %d" % len(poryadok))

        cifry = {"vse": len(poryadok), "kiev": 0, "georgia": 0,
                 "sea": 0, "korea": 0}
        fantomy = []
        for kod in poryadok:
            et = baza.get(kod)
            if et is None:
                fantomy.append(kod)
                continue
            if et in cifry:
                cifry[et] += 1
        obychno = min(skolko.values()) if skolko else 0
        for kod in poryadok:
            if obychno and skolko.get(kod, 0) >= 2 * obychno:
                zapis = "%s: ссылок %d, у остальных машин по %d" % (
                    kod, skolko[kod], obychno)
                if zapis not in dubli_vse:
                    dubli_vse.append(zapis)
        fantomy_vse += [k for k in fantomy if k not in fantomy_vse]

        skazat("должно быть: всего %d | Киев %d | Грузия %d | море %d | Корея %d"
               % (cifry["vse"], cifry["kiev"], cifry["georgia"],
                  cifry["sea"], cifry["korea"]))

        novyy, zameny = pochinit_podpisi(tekst, cifry)
        if zameny:
            for z in zameny:
                skazat("  исправлено в тексте -> " + z)
        else:
            skazat("  числа в тексте страницы менять не пришлось")

        novyy = postavit_storozh(novyy)

        vremenny = put + ".novyy"
        try:
            with open(vremenny, "w", encoding="utf-8") as f:
                f.write(novyy)
            proverka = open(vremenny, "r", encoding="utf-8").read()
            if "ua-cifry-storozh" not in proverka or len(proverka) < len(tekst) * 0.5:
                os.remove(vremenny)
                skazat("!! проверка нового файла не прошла, страница НЕ изменена")
                continue
            os.replace(vremenny, put)
            tronuto += 1
            skazat("  сторож цифр поставлен, файл записан")
        except Exception as osh:
            skazat("!! запись не удалась: " + str(osh))
            try:
                if os.path.exists(vremenny):
                    os.remove(vremenny)
            except Exception:
                pass

    skazat("")
    skazat("=" * 52)
    skazat("ИТОГ")
    skazat("страниц каталога исправлено: %d" % tronuto)
    if fantomy_vse:
        skazat("!! на сайте есть карточки, которых НЕТ в базе: "
               + ", ".join(fantomy_vse))
    else:
        skazat("карточек-призраков (нет в базе) не найдено")
    if dubli_vse:
        skazat("!! подозрение на двойные карточки: " + "; ".join(dubli_vse))
        skazat("   дубли будут скрыты сторожем при открытии страницы")
    else:
        skazat("двойных ссылок на одну машину в тексте не видно")
    net_na_sayte = [k for k in baza if k not in
                    sum([kody_na_stranice(open(os.path.join(p, "katalog.html"),
                                               encoding="utf-8",
                                               errors="replace").read())[0]
                         for p in PAPKI
                         if os.path.exists(os.path.join(p, "katalog.html"))], [])]
    if net_na_sayte:
        skazat("В базе есть, а в каталоге нет: " + ", ".join(sorted(net_na_sayte)))
    skazat("резерв старых файлов: " + REZERV)
    skazat("Откат: вернуть katalog.html из папки резерва на свои места")
    skazat("=" * 52)

    imya = "otchet_cifry_%s_%04d.txt" % (MOMENT, random.randint(0, 9999))
    try:
        with open(os.path.join(DOM, imya), "w", encoding="utf-8") as f:
            f.write("\n".join(otchet))
        print("Отчёт: /home/Carix/" + imya)
    except Exception:
        pass


main()

full_sources.fixclick.py:
# -*- coding: utf-8 -*-
# FIXCLICK (UA-FIXCLICK-V1) — КЛИК ПО ЧИПУ ВНУТРИ КАТАЛОГА.
#
# Установлено: активный чип уже переключается (UA-FIXCHIP-V2 работает), но
# при клике внутри каталога показывается 0 машин. Причина: родной обработчик
# вешает карточкам inline display:none и сопоставить их с этапом не может —
# у карточек data-stage, а у кнопок data-f.
#
# Этот блок при клике делает всё одним действием:
#   1) определяет выбранный этап из data-f;
#   2) ставит document.documentElement.dataset.etapFiltr — включает рабочий CSS;
#   3) обновляет адрес через history.replaceState на ?f=..&stage=..;
#   4) переносит active и aria-pressed;
#   5) СНИМАЕТ inline display со всех .catalog-card — решает только CSS;
#   6) пересчитывает «Показано» по фактически видимым карточкам.
# Для «Все» атрибут удаляется и видны все восемь.
#
# Меняется РОВНО ОДИН файл — i18n.js. Карточки, CRM, стадии, data-stage,
# диагностика, stranica.py и работающий CSS-фильтр не трогаются.

import os, io, re, glob, json, time, shutil, hashlib

DOM = "/home/Carix"
VIDEO = DOM + "/video"
SITE = DOM + "/site"
BAZA = DOM + "/crm.db"
SAIT = "https://www.uaart.com.ua"
KATALOG = VIDEO + "/katalog.html"
BASELINE = DOM + "/PROTECTED_BASELINE.json"
METKA = time.strftime("%Y%m%d_%H%M%S")
REZERV = DOM + "/rezerv_fixclick_" + METKA
METKA_BLOKA = "UA-FIXCLICK-V1"

KOD = """
/* ===== %s: клик по чипу внутри каталога ==========================
   Родной обработчик вешает карточкам inline display:none и прячет все,
   потому что сопоставляет data-f с data-stage. Здесь inline-стиль
   снимается, а решение остаётся за уже работающим CSS-правилом
   html[data-etap-filtr] .catalog-card:not([data-stage=...]).
   ================================================================= */
(function(){
  try{
    var KARTA = {kiev:'kiev', gruzia:'georgia', georgia:'georgia',
                 more:'sea', sea:'sea', korea:'korea', all:'all', vse:'all'};

    function normalizovat(z){
      z = (z || '').toLowerCase();
      return KARTA[z] || z;
    }

    function snyat_inline(){
      var karty = document.querySelectorAll('.catalog-card');
      for (var i = 0; i < karty.length; i++){
        if (karty[i].style && karty[i].style.display){
          karty[i].style.removeProperty('display');
        }
        if (karty[i].hasAttribute('hidden')){
          karty[i].removeAttribute('hidden');
        }
      }
      return karty.length;
    }

    function vidimyh(){
      var karty = document.querySelectorAll('.catalog-card'), n = 0;
      for (var i = 0; i < karty.length; i++){
        var st = window.getComputedStyle ? window.getComputedStyle(karty[i]) : null;
        if (st && (st.display === 'none' || st.visibility === 'hidden')) continue;
        n++;
      }
      return n;
    }

    function pokazano(){
      var n = vidimyh();
      var vse = document.querySelectorAll('a,span,button,div,li,p,em,b,strong,small');
      for (var i = 0; i < vse.length; i++){
        var e = vse[i];
        if (e.children && e.children.length > 0) continue;
        var t = (e.textContent || '').replace(/\\s+/g, ' ').trim();
        if (/^(Показано|Показанo|Показуємо)\\s*:?\\s*\\d+$/.test(t)){
          var novoe = t.replace(/\\d+/, String(n));
          if (t !== novoe) e.textContent = novoe;
        }
      }
      return n;
    }

    function chipy(vybran){
      var spisok = document.querySelectorAll('[data-f]');
      for (var i = 0; i < spisok.length; i++){
        var c = spisok[i];
        var svoy = normalizovat(c.getAttribute('data-f')) === vybran;
        if (svoy){ c.classList.add('active'); c.setAttribute('aria-pressed','true'); }
        else { c.classList.remove('active'); c.setAttribute('aria-pressed','false'); }
      }
    }

    function primenit(vybran, menyat_adres){
      vybran = normalizovat(vybran || 'all');
      if (vybran === 'all'){
        document.documentElement.removeAttribute('data-etap-filtr');
      } else {
        document.documentElement.setAttribute('data-etap-filtr', vybran);
      }
      chipy(vybran);
      snyat_inline();
      if (menyat_adres && window.history && history.replaceState){
        var adres = location.pathname + (vybran === 'all'
          ? '' : ('?f=' + vybran + '&stage=' + vybran));
        try{ history.replaceState(null, '', adres); }catch(e){}
      }
      pokazano();
      // родной обработчик может отработать позже — повторяем
      setTimeout(function(){ snyat_inline(); pokazano(); }, 60);
      setTimeout(function(){ snyat_inline(); pokazano(); }, 250);
      setTimeout(function(){ snyat_inline(); pokazano(); }, 600);
    }

    function iz_adresa(){
      var par = new URLSearchParams(location.search);
      return normalizovat(par.get('stage') || par.get('f') || 'all');
    }

    function zapusk(){
      primenit(iz_adresa(), false);
      document.addEventListener('click', function(sob){
        var el = sob.target;
        while (el && el !== document.documentElement && !el.hasAttribute('data-f')){
          el = el.parentElement;
        }
        if (!el || !el.hasAttribute('data-f')) return;
        primenit(el.getAttribute('data-f'), true);
      }, true);
      window.addEventListener('popstate', function(){ primenit(iz_adresa(), false); });
      window.addEventListener('hashchange', function(){ primenit(iz_adresa(), false); });
    }

    if (document.readyState === 'loading'){
      document.addEventListener('DOMContentLoaded', zapusk);
    } else { zapusk(); }
  }catch(e){}
})();
/* ===== конец %s ===== */
""" % (METKA_BLOKA, METKA_BLOKA)

STROKI = []
ITOG = []


def p(s=""):
    STROKI.append(str(s))


def zagolovok(t):
    p("")
    p("=" * 62)
    p(t)
    p("=" * 62)


def itog(imya, sost, kom=""):
    ITOG.append((imya, sost if isinstance(sost, str) else ("PASS" if sost else "FAIL"), kom))


def sha(put):
    try:
        h = hashlib.sha256()
        with open(put, "rb") as f:
            while True:
                k = f.read(1 << 20)
                if not k:
                    break
                h.update(k)
        return h.hexdigest()
    except Exception:
        return ""


def chitat(put, predel=30 * 1024 * 1024):
    try:
        with io.open(put, "r", encoding="utf-8", errors="ignore") as f:
            return f.read(predel)
    except Exception:
        return ""


def snimok():
    s = {}
    for x in sorted(glob.glob(VIDEO + "/*.html") + glob.glob(SITE + "/*.html")
                    + glob.glob(VIDEO + "/**/*.css", recursive=True)
                    + glob.glob(VIDEO + "/**/*.js", recursive=True)):
        s[x] = sha(x)
    s[BAZA] = sha(BAZA)
    s[BASELINE] = sha(BASELINE)
    return s


def nayti_js():
    html = chitat(KATALOG)
    for adres in re.findall(r"<script\b[^>]*src\s*=\s*['\"]([^'\"]+)['\"]", html, re.I):
        chistyy = adres.split("?")[0]
        if not chistyy.endswith(".js"):
            continue
        put = os.path.join(VIDEO, chistyy[len("/video/"):]) if chistyy.startswith("/video/") \
            else os.path.join(VIDEO, chistyy.lstrip("/"))
        if os.path.isfile(put):
            return put, adres
    return "", ""


# ==========================================  1 РОДНОЙ ОБРАБОТЧИК
def etap1(html, js):
    zagolovok("1. КТО СЕЙЧАС ОБРАБАТЫВАЕТ КЛИК ПО ЧИПУ")
    vstroennye = re.findall(r"<script(?![^>]*\bsrc\b)[^>]*>(.*?)</script>", html, re.S | re.I)
    ves = "\n".join(vstroennye)
    p("встроенного кода в каталоге: %d знаков" % len(ves))
    stroki = [(n, s) for n, s in enumerate(ves.split("\n"), 1)
              if re.search(r"data-f|style\.display|display\s*=", s)]
    p("строки, где встречается data-f или скрытие:")
    for n, s in stroki[:15]:
        p("%4d| %s" % (n, s.strip()[:130]))
    if not stroki:
        p("   во встроенном коде таких строк нет")
    p("")
    p("во внешнем js упоминаний data-f: %d" % len(re.findall(r"data-f", js)))
    p("во внешнем js операций style.display: %d" % len(re.findall(r"style\.display", js)))
    itog("РОДНОЙ ОБРАБОТЧИК НАЙДЕН", bool(stroki) or "data-f" in js, "строк %d" % len(stroki))


# ==========================================  2 ПРАВКА
def etap2(js_put):
    zagolovok("2. ПРАВКА: БЛОК В КОНЕЦ i18n.js")
    bylo = chitat(js_put)
    if METKA_BLOKA in bylo:
        p("блок %s уже стоит — повторно не добавляю" % METKA_BLOKA)
        return bylo, True
    p("что делает добавляемый блок при клике по чипу:")
    p("   · нормализует значение data-f в этап;")
    p("   · ставит или снимает data-etap-filtr на <html>;")
    p("   · переносит active и aria-pressed;")
    p("   · СНИМАЕТ inline display со всех .catalog-card;")
    p("   · обновляет адрес через replaceState на ?f=..&stage=..;")
    p("   · пересчитывает «Показано» по видимым карточкам;")
    p("   · повторяет снятие и пересчёт через 60, 250 и 600 мс,")
    p("     чтобы отработать после родного обработчика")
    stalo = bylo.rstrip("\n") + "\n" + KOD
    with io.open(js_put, "w", encoding="utf-8") as f:
        f.write(stalo)
    teper = chitat(js_put)
    bez = teper.replace(KOD, "").rstrip("\n")
    sovpalo = bez == bylo.rstrip("\n")
    p("")
    p("файл: %d → %d знаков (разница %d)" % (len(bylo), len(teper), len(teper) - len(bylo)))
    p("после удаления блока совпадает с исходником: %s" % ("ДА" if sovpalo else "НЕТ"))
    itog("DIFF ONLY NEW BLOCK", sovpalo, "%d байт" % (len(teper) - len(bylo)))
    return teper, sovpalo


# ==========================================  3 ПРОВЕРКА
def etap3(js, html):
    zagolovok("3. ПРОВЕРКА СОДЕРЖИМОГО")
    trebovaniya = (
        ("снятие inline display", "removeProperty('display')"),
        ("снятие hidden", "removeAttribute('hidden')"),
        ("установка data-etap-filtr", "setAttribute('data-etap-filtr'"),
        ("удаление при all", "removeAttribute('data-etap-filtr')"),
        ("перенос active", "classList.add('active')"),
        ("снятие active", "classList.remove('active')"),
        ("aria-pressed true", "'aria-pressed','true'"),
        ("aria-pressed false", "'aria-pressed','false'"),
        ("обновление адреса", "history.replaceState"),
        ("пересчёт показано", "Показано"),
        ("повтор после родного", "setTimeout"),
    )
    vse = True
    for imya, obrazec in trebovaniya:
        est = obrazec in js
        p("   %-28s %s" % (imya, "есть" if est else "НЕТ"))
        if not est:
            vse = False
    p("")
    # соответствие разметке
    chipy = re.findall(r'data-f\s*=\s*["\']([^"\']+)["\']', html)
    kartochki = len(re.findall(r'class\s*=\s*["\'][^"\']*catalog-card', html))
    p("чипов в разметке: %s" % ", ".join(chipy))
    p("карточек с классом catalog-card: %d" % kartochki)
    p("значения чипов покрыты картой: %s"
      % ("да" if all(c in ("all", "kiev", "georgia", "sea", "korea") for c in chipy) else "НЕТ"))
    itog("ЛОГИКА ПОЛНАЯ", vse and kartochki == 8, "%d карточек" % kartochki)
    for st, skolko in (("KIEV", 3), ("GEORGIA", 1), ("SEA", 2), ("KOREA", 2)):
        itog("%s INTERNAL CLICK" % st, vse and kartochki == 8,
             "ждёт проверки на iPhone, ожидается %d" % skolko)
    itog("ALL INTERNAL CLICK", vse and kartochki == 8, "ждёт проверки, ожидается 8")
    return vse and kartochki == 8


def etap4(s_do, js_put):
    zagolovok("4. ЧТО ИЗМЕНИЛОСЬ НА ДИСКЕ")
    izmenilos = [x for x in s_do if sha(x) != s_do[x]]
    lishnie = [x for x in izmenilos if x != js_put]
    p("изменившихся файлов: %d" % len(izmenilos))
    for x in izmenilos:
        p("   %s%s" % (x.replace(DOM, ""), "" if x == js_put else "   ← НЕ ОЖИДАЛОСЬ"))
    kartochki = [x for x in izmenilos if re.search(r"UA-\d{4}", x)]
    p("")
    p("CARDS CHANGED: %d · CRM CHANGED: %s · CSS CHANGED: %d"
      % (len(kartochki), "ДА" if BAZA in izmenilos else "NO",
         len([x for x in izmenilos if x.endswith(".css")])))
    itog("UNEXPECTED FILES CHANGED", str(len(lishnie)), "")
    itog("CARDS CHANGED", str(len(kartochki)), "")
    itog("CSS FILTER UNTOUCHED", not [x for x in izmenilos if x.endswith(".css")], "")
    return not lishnie


def otkat(js_put, prichina):
    p("")
    p("ОТКАТ: %s" % prichina)
    try:
        shutil.copy2(REZERV + "/" + os.path.basename(js_put), js_put)
        p("i18n.js возвращён, SHA %s" % sha(js_put))
    except Exception as e:
        p("ОТКАТ НЕ УДАЛСЯ: %r" % e)


# ==========================================  ЗАПУСК
def main():
    p("FIXCLICK (UA-FIXCLICK-V1) — КЛИК ПО ЧИПУ ВНУТРИ КАТАЛОГА")
    p("время: " + time.strftime("%Y-%m-%d %H:%M:%S"))
    p("фильтрация по прямой ссылке и CSS-правило не трогаются")

    js_put, js_adres = nayti_js()
    if not js_put:
        p("внешний js не найден")
        itog("PRODUCTION WRITE PERFORMED", "NO", "js не найден")
    else:
        p("внешний js: %s (%s)" % (js_put.replace(DOM, ""), js_adres))
        os.makedirs(REZERV, exist_ok=True)
        shutil.copy2(js_put, REZERV + "/" + os.path.basename(js_put))
        p("резерв: %s" % REZERV)
        s_do = snimok()
        html = chitat(KATALOG)
        etap1(html, chitat(js_put))
        js, tochno = etap2(js_put)
        polno = etap3(js, html)
        chisto = etap4(s_do, js_put)
        if not (tochno and polno and chisto):
            otkat(js_put, "проверка не пройдена")
            itog("ROLLBACK NOT REQUIRED", False, "откат выполнен")
            itog("PRODUCTION WRITE PERFORMED", "NO", "правка откачена")
        else:
            itog("ROLLBACK NOT REQUIRED", True, "откат не понадобился")
            itog("PRODUCTION WRITE PERFORMED", "YES", os.path.basename(js_put))

    zagolovok("ИТОГОВАЯ СВОДКА FIXCLICK")
    for imya, sost, kom in ITOG:
        p("%-34s %-8s %s" % (imya, sost, kom))
    p("")
    p("резерв: %s" % (REZERV if os.path.isdir(REZERV) else "не создавался"))
    p("")
    p("ВАЖНО ПРО КЭШ: i18n.js подключён с фиксированным хвостом, поэтому")
    p("проверяйте в ПРИВАТНОЙ вкладке Safari — там старый файл не подставится.")
    p("")
    p("ПРОВЕРЬТЕ ПОДРЯД, НЕ ПЕРЕЗАГРУЖАЯ СТРАНИЦУ:")
    p("   1. открыть %s/video/katalog.html" % SAIT)
    p("   2. нажать «В Киеве»  — жёлтая, показано 3, видно 3")
    p("   3. нажать «В Грузии» — жёлтая, показано 1, видно 1")
    p("   4. нажать «В море»   — жёлтая, показано 2, видно 2")
    p("   5. нажать «В Корее»  — жёлтая, показано 2, видно 2")
    p("   6. нажать «Все»      — жёлтая, показано 8, видно 8")

    tekst = "\n".join(STROKI)
    imya = "fixclick" + hashlib.sha256((METKA + tekst[:400]).encode()).hexdigest()[:8] + ".txt"
    try:
        with io.open(VIDEO + "/" + imya, "w", encoding="utf-8") as f:
            f.write(tekst)
        with io.open(VIDEO + "/otchet.txt", "w", encoding="utf-8") as f:
            f.write(tekst)
    except Exception as e:
        print("отчёт не записан: %r" % e)
    print("=" * 52)
    print("FIXCLICK ЗАВЕРШЁН")
    print("=" * 52)
    for i, s, kk in ITOG:
