        r'<(?P<tag>a|button|section|aside)\b(?=[^>]*\bclass=["\'][^"\']*\b'
        + legacy + r'\b[^"\']*["\'])[^>]*>.*?</(?P=tag)\s*>',
        _ua068_re.I | _ua068_re.S,
