# -*- coding: utf-8 -*-
"""
UA ART · ПАКЕТ + РАЗМЕЩЕНИЕ НОВЫХ МАШИН (UA-0006 и все будущие)
Ставится в /home/Carix ВМЕСТЕ с архивом uaart_fixes.zip.
Запускается кнопкой Run this file. Запускать можно многократно:
каждый запуск дособирает машины, появившиеся в CRM.

Порядок:
  1) пакет линии: katalog.html + ua-v203.css + i18n.js в обе папки,
     дозапись нашего блока этапов (в пакете его нет);
  2) чтение crm.db ТОЛЬКО НА ЧТЕНИЕ: какие машины есть в базе;
  3) для каждой машины без страницы (сейчас UA-0006):
       — страница машины: клон утверждённой страницы той же марки
         с заменой значений (цена, пробег, VIN, год, имя) по базе;
       — галерея по фактическим фото /video/foto/UA-XXXX/;
       — страница диагностики: клон с заменой номера и медиа;
       — карточка в каталог: клон карточки того же этапа с заменой
         значений по базе;
       — счётчик машин на карточке этапа главной и в кнопке
         «Открыть все автомобили»;
  4) свежие версии ?v=, самопроверка, отчёт.

Не изменяет: crm.db, ботов, фото, видео, stranica.py, ua.css.
Каждая замена значения печатается в отчёт. Если какое-то значение
найти не удалось — это видно, и машина помечается «проверить глазами».
"""

import os, re, html, time, shutil, hashlib, zipfile, sqlite3, datetime

DOM = "/home/Carix"
ZIP = os.path.join(DOM, "uaart_fixes.zip")
VIDEO = os.path.join(DOM, "video")
PREV = os.path.join(VIDEO, "preview", "v4")
DB = os.path.join(DOM, "crm.db")
METKA = datetime.datetime.now().strftime("%Y%m%d_%H%M")
stroki = []
def p(s=""):
    print(s)
    stroki.append(str(s))

p("UA ART · ПАКЕТ + РАЗМЕЩЕНИЕ НОВЫХ МАШИН")
p("время: " + datetime.datetime.now().strftime("%d.%m.%Y %H:%M:%S"))
p("")

rezerv = os.path.join(DOM, "rezerv_vse_" + METKA)
os.makedirs(rezerv, exist_ok=True)
def v_rezerv(put):
    if os.path.exists(put):
        cel = os.path.join(rezerv, os.path.relpath(put, DOM))
        os.makedirs(os.path.dirname(cel), exist_ok=True)
        if not os.path.exists(cel):
            shutil.copy2(put, cel)
def zapis(put, tekst):
    v_rezerv(put)
    vr = put + ".vr"
    open(vr, "w", encoding="utf-8").write(tekst)
    os.replace(vr, put)

# ================================================= 1. ПАКЕТ ЛИНИИ
p("=" * 58)
p("1. ПАКЕТ ЛИНИИ + БЛОК ЭТАПОВ")
p("=" * 58)
if os.path.exists(ZIP):
    razb = os.path.join(DOM, "_paket_" + METKA)
    with zipfile.ZipFile(ZIP) as z:
        z.extractall(razb)
    nuzhnye = ["video/katalog.html", "video/ua-v203.css", "video/i18n.js",
               "video/preview/v4/katalog.html", "video/preview/v4/ua-v203.css",
               "video/preview/v4/i18n.js"]
    if all(os.path.exists(os.path.join(razb, f)) for f in nuzhnye):
        css_pak = open(os.path.join(razb, "video", "ua-v203.css"), encoding="utf-8").read()
        if css_pak.count("{") == css_pak.count("}"):
            for otn in nuzhnye:
                v_rezerv(os.path.join(DOM, otn))
                shutil.copy2(os.path.join(razb, otn), os.path.join(DOM, otn) + ".vr")
                os.replace(os.path.join(DOM, otn) + ".vr", os.path.join(DOM, otn))
            p("пакет установлен в обе папки")
        else:
            p("!! в css пакета не сходятся скобки — пакет пропущен")
    else:
        p("!! в архиве не хватает файлов — пакет пропущен")
else:
    p("архива uaart_fixes.zip нет — считаю, что пакет уже стоит")

# фильтр этапов ставится СРАЗУ после пакета — пакет линии его не содержит,
# и без этого шага все машины видны на всех этапах («общий котёл»)
STOROZH_F = ("<script>/* UA ART фильтр этапов v3 */\n"
  "(function(){\n"
  "  var par=new URLSearchParams(location.search);\n"
  "  var st=par.get('stage')||par.get('f');\n"
  "  if(!st) return;\n"
  "  var karta={kiev:'kiev',gruzia:'georgia',georgia:'georgia',more:'sea',sea:'sea',korea:'korea'};\n"
  "  st=karta[st]||st;\n"
  "  document.documentElement.setAttribute('data-etap-filtr',st);\n"
  "})();\n"
  "</script>")
CSS_F = """/* ===== UA ART · ФИЛЬТР ЭТАПОВ СТИЛЕМ ===== */
html[data-etap-filtr="kiev"]    .catalog-card:not([data-stage="kiev"]),
html[data-etap-filtr="georgia"] .catalog-card:not([data-stage="georgia"]),
html[data-etap-filtr="sea"]     .catalog-card:not([data-stage="sea"]),
html[data-etap-filtr="korea"]   .catalog-card:not([data-stage="korea"]){
  display:none !important;
}
/* ===== конец ===== */
"""
MARK_F = "/* ===== UA ART · ФИЛЬТР ЭТАПОВ СТИЛЕМ ===== */"
for koren in (VIDEO, PREV):
    put_kat = os.path.join(koren, "katalog.html")
    if os.path.exists(put_kat):
        kat_f = open(put_kat, encoding="utf-8", errors="ignore").read()
        kat_f = re.sub(r'<script>/\* UA ART фильтр этапов v\d \*/.*?</script>\n?', "", kat_f, flags=re.S)
        if "<head>" in kat_f:
            kat_f = kat_f.replace("<head>", "<head>\n" + STOROZH_F + "\n", 1)
        else:
            kat_f = STOROZH_F + "\n" + kat_f
        zapis(put_kat, kat_f)
    put_c = os.path.join(koren, "ua-v203.css")
    if os.path.exists(put_c):
        c_f = open(put_c, encoding="utf-8").read()
        if MARK_F in c_f:
            c_f = c_f.split(MARK_F)[0].rstrip() + "\n"
        c_f = c_f.rstrip() + "\n\n" + CSS_F
        if c_f.count("{") == c_f.count("}"):
            zapis(put_c, c_f)
p("фильтр этапов поставлен вместе с пакетом (сторож v3 + стиль)")

BLOK = """/* ===== UA ART · ЭТАПЫ: ГОТОВАЯ ПРАВКА ===== */
html, body{ max-width:100% !important; overflow-x:hidden !important; }
#stages .stage-list{
  display:grid !important; grid-template-columns:1fr !important;
  width:100% !important; max-width:100% !important; min-width:0 !important; box-sizing:border-box !important;
}
a.stage-card{
  position:relative !important; width:100% !important; max-width:100% !important; min-width:0 !important;
  box-sizing:border-box !important; aspect-ratio:620/234 !important; height:auto !important;
  border:1px solid #efa938 !important; border-radius:18px !important; overflow:hidden !important;
}
.stage-card .stage-picture, .stage-card .stage-ai{
  position:absolute !important; left:0 !important; top:0 !important; right:auto !important;
  width:50% !important; height:100% !important; object-fit:cover !important;
  object-position:center center !important; z-index:0 !important;
}
.stage-card .stage-live{
  position:absolute !important; right:0 !important; left:auto !important; top:0 !important;
  width:50% !important; height:100% !important; object-fit:cover !important;
  object-position:center center !important; z-index:0 !important;
}
.stage-card .stage-blend{
  position:absolute !important; top:0 !important; bottom:0 !important;
  left:calc(50% - 14px) !important; right:auto !important; width:28px !important; height:100% !important;
  z-index:2 !important; transform:none !important; pointer-events:none !important; box-shadow:none !important;
  background:linear-gradient(90deg, rgba(11,24,42,.16) 0%, rgba(11,24,42,.04) 55%, rgba(11,24,42,0) 100%) !important;
  -webkit-backdrop-filter:blur(4px) !important; backdrop-filter:blur(4px) !important;
  -webkit-mask-image:linear-gradient(90deg, transparent, #000 40%, #000 60%, transparent) !important;
          mask-image:linear-gradient(90deg, transparent, #000 40%, #000 60%, transparent) !important;
}
.stage-card .stage-content{ max-width:50% !important; min-width:0 !important; box-sizing:border-box !important; z-index:3 !important; }
.stage-card .stage-copy{ min-width:0 !important; overflow-wrap:anywhere; }
/* ===== конец ===== */
"""
MARK = "/* ===== UA ART · ЭТАПЫ: ГОТОВАЯ ПРАВКА ===== */"
for koren in (VIDEO, PREV):
    put_css = os.path.join(koren, "ua-v203.css")
    t = open(put_css, encoding="utf-8").read()
    if MARK in t:
        t = t.split(MARK)[0].rstrip() + "\n"
    t = t.rstrip() + "\n\n" + BLOK
    if t.count("{") == t.count("}"):
        zapis(put_css, t)
p("блок этапов дозаписан в оба css")

# ================================================= 2. БАЗА
p("")
p("=" * 58)
p("2. ЧТЕНИЕ CRM (только чтение)")
p("=" * 58)
ETAP_PO_STATUSU = {"ua_arrived": "kiev", "ge_waiting": "georgia",
                   "sea_loaded": "sea", "kr_bought": "korea"}
con = sqlite3.connect("file:" + DB + "?mode=ro", uri=True)
con.row_factory = sqlite3.Row
tabl = None
for (imya,) in con.execute("SELECT name FROM sqlite_master WHERE type='table'"):
    try:
        r = con.execute("SELECT * FROM %s LIMIT 1" % imya).fetchone()
    except Exception:
        continue
    if r and any(isinstance(v, str) and re.match(r'^UA-\d+$', v) for v in tuple(r)):
        tabl = imya
        break
if not tabl:
    p("!! в crm.db не нашлась таблица машин — стоп")
    raise SystemExit
kolonki = [c[1] for c in con.execute("PRAGMA table_info(%s)" % tabl)]
def kol(*varianty):
    for v in varianty:
        if v in kolonki:
            return v
    return None
K_KOD = kol("auto_number", "kod", "code", "nomer", "number")
K_MARKA = kol("brand", "marka", "make")
K_MODEL = kol("model")
K_GOD = kol("year", "god")
K_CENA = kol("price_total", "price", "cena")
K_CENA2 = kol("price_uah")
K_CENA3 = kol("cost_total")
K_CENA4 = kol("price_buy")
K_OBEM = kol("engine_cc", "engine")
K_TOPL = kol("fuel")
K_KPP = kol("gearbox")
K_KONT = kol("sea_container")
K_OTPR = kol("sea_date_out")
K_ETA = kol("eta_manual")

def cena_mashiny(d):
    for k in (K_CENA, K_CENA2, K_CENA3, K_CENA4):
        v = znach(d, k)
        if v and v != "0":
            return v
    return ""
K_PROBEG = kol("mileage_km", "mileage", "probeg", "km")
K_VIN = kol("vin")
K_ETAP1 = kol("stage")
K_ETAP2 = kol("status")
p("таблица: %s · колонки: %s" % (tabl, ", ".join(kolonki)))
mashiny = {}
for r in con.execute("SELECT * FROM %s" % tabl):
    d = dict(r)
    kod = d.get(K_KOD)
    if kod and re.match(r'^UA-\d+$', str(kod)):
        mashiny[str(kod)] = d
con.close()
p("машин в базе: %d — %s" % (len(mashiny), ", ".join(sorted(mashiny))))

# ================================================= 3. НОВЫЕ МАШИНЫ
def znach(d, k):
    v = "" if k is None or d.get(k) is None else str(d[k]).strip()
    if v.endswith(".0"):
        v = v[:-2]
    return v

def etap_mashiny(d):
    """этап берём из той колонки (stage/status), где лежит знакомый код"""
    for k in (K_ETAP1, K_ETAP2):
        v = znach(d, k)
        if v in ETAP_PO_STATUSU:
            return ETAP_PO_STATUSU[v], v
    return None, znach(d, K_ETAP1) or znach(d, K_ETAP2)

def s_probelom(v):
    """16900 -> 16 900, как пишется на страницах"""
    if v.isdigit() and len(v) > 3:
        r = ""
        while len(v) > 3:
            r = " " + v[-3:] + r
            v = v[:-3]
        return v + r
    return v

def s_probelom_lyuboy(v):
    """тысячный пробел для любого числа длиннее трёх цифр (1800 -> 1 800)"""
    v = ("" if v is None else str(v)).strip()
    if v.endswith(".0"):
        v = v[:-2]
    if v.isdigit() and len(v) > 3:
        r = ""
        while len(v) > 3:
            r = " " + v[-3:] + r
            v = v[:-3]
        return v + r
    return v

def podmena(tekst, staroe, novoe, imya_polya, zhurnal, god=False):
    staroe = ("" if staroe is None else str(staroe)).strip()
    novoe = ("" if novoe is None else str(novoe)).strip()
    if staroe.endswith(".0"):
        staroe = staroe[:-2]
    if novoe.endswith(".0"):
        novoe = novoe[:-2]
    if not staroe or not novoe or staroe == novoe:
        zhurnal.append("      %-10s без замены" % imya_polya)
        return tekst
    varianty = [staroe]
    if not god and s_probelom_lyuboy(staroe) not in varianty:
        varianty.append(s_probelom_lyuboy(staroe))
    nashlos = None
    for star in varianty:
        if star and star in tekst:
            nashlos = star
            break
    if nashlos:
        nov = s_probelom_lyuboy(novoe) if (" " in nashlos and not god) else novoe
        zhurnal.append("      %-10s %s -> %s" % (imya_polya, nashlos, nov))
        return tekst.replace(nashlos, nov)
    zhurnal.append("      %-10s !! «%s» в шаблоне не найдено — проверьте глазами" % (imya_polya, staroe))
    return tekst

p("")
p("=" * 58)
p("3. РАЗМЕЩЕНИЕ НОВЫХ МАШИН")
p("=" * 58)
est_stranicy = set(f[:-5] for f in os.listdir(VIDEO) if re.match(r'^UA-\d+\.html$', f))
kat_tek = open(os.path.join(VIDEO, "katalog.html"), encoding="utf-8", errors="ignore").read()
novye = [k for k in sorted(mashiny)
         if k not in est_stranicy or (k + ".html") not in kat_tek]
p("страницы уже есть: %s" % ", ".join(sorted(est_stranicy)))
p("надо разместить или вернуть в каталог: %s" % (", ".join(novye) or "никого"))
neraspoznannye = []

razmesheno = []
for kod in novye:
    d = mashiny[kod]
    etap, status = etap_mashiny(d)
    if etap is None:
        p("   %s · статус «%s» не распознан — машину пропускаю, сообщите Claude" % (kod, status))
        neraspoznannye.append(kod)
        continue
    foto_dir = os.path.join(VIDEO, "foto", kod)
    skolko_foto = len([f for f in os.listdir(foto_dir)
                       if f.lower().endswith((".jpg", ".jpeg", ".webp", ".png"))]) if os.path.isdir(foto_dir) else 0
    p("")
    p("   %s · %s %s %s · этап %s · фото %d" %
      (kod, znach(d, K_MARKA), znach(d, K_MODEL), znach(d, K_GOD), etap, skolko_foto))
    if skolko_foto == 0:
        p("      !! фото на сервере нет — машину пропускаю (добавьте фото в CRM)")
        continue

    # шаблон: сперва машина ТОГО ЖЕ ЭТАПА (чтобы этапные подписи и даты
    # были родные), затем та же марка, затем любой
    shablon = None
    for kand in sorted(est_stranicy):
        if kand in mashiny and etap_mashiny(mashiny[kand])[0] == etap:
            shablon = kand
            break
    if shablon is None:
        for kand in sorted(est_stranicy):
            if kand in mashiny and znach(mashiny[kand], K_MARKA) == znach(d, K_MARKA):
                shablon = kand
                break
    if shablon is None and est_stranicy:
        shablon = sorted(est_stranicy)[0]
    sd = mashiny.get(shablon, {})
    p("      шаблон страницы: %s" % shablon)

    zh = []
    for koren in (VIDEO, PREV):
        if os.path.exists(os.path.join(koren, kod + ".html")):
            continue
        t = open(os.path.join(koren, shablon + ".html"), encoding="utf-8", errors="ignore").read()
        t = t.replace(shablon, kod)                             # номера и пути к фото
        zh2 = []
        t = podmena(t, znach(sd, K_MARKA), znach(d, K_MARKA), "марка", zh2)
        t = podmena(t, znach(sd, K_MODEL), znach(d, K_MODEL), "модель", zh2)
        t = podmena(t, znach(sd, K_GOD),   znach(d, K_GOD),   "год",   zh2, god=True)
        st_cena, nv_cena = cena_mashiny(sd), cena_mashiny(d)
        if st_cena and nv_cena:
            t = podmena(t, st_cena, nv_cena, "цена", zh2)
        elif st_cena and not nv_cena:
            for star in (s_probelom_lyuboy(st_cena) + " $", s_probelom_lyuboy(st_cena), st_cena):
                if star in t:
                    t = t.replace(star, "Цена уточняется")
                    zh2.append("      %-10s в CRM пусто -> «Цена уточняется»" % "цена")
                    break
        t = podmena(t, znach(sd, K_PROBEG), znach(d, K_PROBEG), "пробег", zh2)
        t = podmena(t, znach(sd, K_VIN),   znach(d, K_VIN),   "VIN",  zh2)
        t = podmena(t, znach(sd, K_OBEM),  znach(d, K_OBEM),  "объём", zh2)
        t = podmena(t, znach(sd, K_TOPL),  znach(d, K_TOPL),  "топливо", zh2)
        t = podmena(t, znach(sd, K_KPP),   znach(d, K_KPP),   "коробка", zh2)
        t = podmena(t, znach(sd, K_KONT),  znach(d, K_KONT),  "контейнер", zh2)
        t = podmena(t, znach(sd, K_OTPR),  znach(d, K_OTPR),  "отправка", zh2)
        st_eta, nv_eta = znach(sd, K_ETA), znach(d, K_ETA)
        if st_eta and nv_eta:
            t = podmena(t, st_eta, nv_eta, "прибытие", zh2)
        elif st_eta and not nv_eta:
            t = t.replace(st_eta, "уточняется")
            zh2.append("      %-10s в CRM пусто -> «уточняется»" % "прибытие")
        # чистим фото, которых нет на диске
        def zhivoe(m):
            nomer = int(m.group(2))
            return m.group(0) if nomer <= skolko_foto else ""
        t = re.sub(r'<img[^>]*foto/%s/0*(\d+)\.(?:jpg|jpeg|webp|png)[^>]*>' % kod,
                   lambda m: m.group(0) if int(re.search(r'/0*(\d+)\.', m.group(0)).group(1)) <= skolko_foto else "",
                   t)
        zapis(os.path.join(koren, kod + ".html"), t)
        if koren == VIDEO:
            zh = zh2
    for s in zh:
        p(s)

    # диагностика: клон с заменой номера
    for koren in (VIDEO, PREV):
        ish = os.path.join(koren, shablon + "-diag.html")
        if os.path.exists(ish) and not os.path.exists(os.path.join(koren, kod + "-diag.html")):
            t = open(ish, encoding="utf-8", errors="ignore").read().replace(shablon, kod)
            zapis(os.path.join(koren, kod + "-diag.html"), t)
    p("      диагностика создана клоном — проверьте её глазами")

    # карточка в каталог: клон карточки того же этапа, иначе шаблонной машины
    for koren in (VIDEO, PREV):
        put_kat = os.path.join(koren, "katalog.html")
        kat = open(put_kat, encoding="utf-8", errors="ignore").read()
        if kod in kat:
            continue
        obrazec = None
        for kand in sorted(est_stranicy):
            m = re.search(r'<article class="catalog-card"[^>]*data-stage="%s"[^>]*>.*?</article>'
                          % etap, kat, re.S)
            if m and kand in m.group(0):
                obrazec = (kand, m.group(0))
                break
        if obrazec is None:
            m = re.search(r'<article class="catalog-card".*?</article>', kat, re.S)
            if m:
                for kand in sorted(est_stranicy):
                    if kand in m.group(0):
                        obrazec = (kand, m.group(0))
                        break
        if obrazec is None:
            p("      !! не нашёл образец карточки каталога — карточку не вставил")
            continue
        kand, blok = obrazec
        sd2 = mashiny.get(kand, {})
        nov = blok.replace(kand, kod)
        nov = re.sub(r'data-stage="[a-z]+"', 'data-stage="%s"' % etap, nov, count=1)
        zh3 = []
        for pole, kk, gd in (("марка", K_MARKA, False), ("модель", K_MODEL, False),
                             ("год", K_GOD, True), ("пробег", K_PROBEG, False),
                             ("объём", K_OBEM, False), ("топливо", K_TOPL, False),
                             ("коробка", K_KPP, False)):
            nov = podmena(nov, znach(sd2, kk), znach(d, kk), pole, zh3, god=gd)
        st_c, nv_c = cena_mashiny(sd2), cena_mashiny(d)
        if st_c and nv_c:
            nov = podmena(nov, st_c, nv_c, "цена", zh3)
        elif st_c and not nv_c:
            for star in (s_probelom_lyuboy(st_c) + " $", s_probelom_lyuboy(st_c), st_c):
                if star in nov:
                    nov = nov.replace(star, "Цена уточняется")
                    zh3.append("      %-10s -> «Цена уточняется»" % "цена")
                    break
        for stroka_zh in zh3:
            p(stroka_zh)
        kat = kat.replace(blok, blok + "\n" + nov, 1)
        zapis(put_kat, kat)
    p("      карточка добавлена в каталог (обе папки)")
    razmesheno.append((kod, etap))

# счётчики на главной
def slovo(n):
    return "%d автомобил%s" % (n, "ь" if n % 10 == 1 and n % 100 != 11 else
                               ("я" if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14 else "ей"))
na_sajte = set(f[:-5] for f in os.listdir(VIDEO) if re.match(r'^UA-\d+\.html$', f))
raspoznany = {k: d for k, d in mashiny.items()
              if k in na_sajte and etap_mashiny(d)[0] is not None}
if raspoznany and len(raspoznany) == len([k for k in mashiny if k in na_sajte]):
    itogo = len(na_sajte)
    schet_po_etapu = {}
    for kod, d in raspoznany.items():
        e = etap_mashiny(d)[0]
        schet_po_etapu[e] = schet_po_etapu.get(e, 0) + 1
    for koren in (VIDEO, PREV):
        put = os.path.join(koren, "index.html")
        t = open(put, encoding="utf-8", errors="ignore").read()
        for e, n in schet_po_etapu.items():
            t = re.sub(r'(data-stage="%s".{0,900}?>)\d+ автомобил[а-я]+' % e,
                       lambda m: m.group(1) + slovo(n), t, count=1, flags=re.S)
        t = re.sub(r'Открыть все автомобили · \d+', "Открыть все автомобили · %d" % itogo, t)
        t = re.sub(r'Відкрити всі автомобілі · \d+', "Відкрити всі автомобілі · %d" % itogo, t)
        zapis(put, t)
    p("")
    p("счётчики на главной обновлены: " +
      " · ".join("%s %d" % (e, n) for e, n in sorted(schet_po_etapu.items())) +
      " · всего %d" % itogo)
else:
    p("")
    p("счётчики не трогаю: не все машины сайта распознаны в базе")
if neraspoznannye:
    p("!! статусы не распознаны у: " + ", ".join(neraspoznannye))

# ================================================= 4. версии и проверка
obnovleno = 0
pravilo = re.compile(r'(href|src)="((?:ua-v\d+\.css|i18n\.js))(\?v=[^"]*)?"')
for koren in (VIDEO, PREV):
    for imya in sorted(os.listdir(koren)):
        if not imya.endswith(".html") or imya.startswith("otchet_"):
            continue
        put = os.path.join(koren, imya)
        t = open(put, encoding="utf-8", errors="ignore").read()
        t2 = pravilo.sub(lambda m: '%s="%s?v=%s"' % (m.group(1), m.group(2), METKA), t)
        if t2 != t:
            zapis(put, t2)
            obnovleno += 1

p("")
p("=" * 58)
p("ПРОВЕРКА")
p("=" * 58)
for koren, imya_k in ((VIDEO, "сайт"), (PREV, "предпросмотр")):
    glav = open(os.path.join(koren, "index.html"), encoding="utf-8", errors="ignore").read()
    kat = open(os.path.join(koren, "katalog.html"), encoding="utf-8", errors="ignore").read()
