"""
UA ART · ЯДРО ВЁРСТКИ (UA-V177)

Вёрстка по шести утверждённым макетам от 18.08.2026.
Данные — из crm.db и файловой системы. Бот и CRM не затрагиваются.
"""

import io
import os
import re
import json
import time
import html as _html

BAZA = "/home/Carix"
PAPKA_VID = os.path.join(BAZA, "video")
DB = os.path.join(BAZA, "crm.db")
PAMYAT_SROK = os.path.join(BAZA, ".srok_gruzia.json")

ADRES_SAYTA = "https://www.uaart.com.ua/video/"
