def hdr(nazad="index.html", pod=True):
    c = ["<header class=\"hdr\"><div class=\"r\">"]
    if nazad:
        c.append("<a class=\"back\" href=\"%s\" aria-label=\"Назад\">←</a>"
                 % ekran(nazad))
    c.append("<div class=\"ua\">UA</div><div class=\"brnd\"><b>UA ART COMPANY</b>")
    if pod:
        c.append("<i>%s</i>" % t("Автомобили из разных стран",
                                 "Автомобілі з різних країн"))
    c.append("</div>")
    c.append("<div class=\"lng\"><button type=\"button\" data-l=\"ru\" class=\"on\" "
             "onclick=\"uaLng('ru')\">RU</button><span></span>"
             "<button type=\"button\" data-l=\"ua\" onclick=\"uaLng('ua')\">UA</button>"
             "</div></div></header>")
    return "".join(c)


def wa_ssylka(tekst=""):
    try:
        from urllib.parse import quote
    except Exception:
        return "[URL]" % WHATSAPP
    if not tekst:
        tekst = "Здравствуйте! Интересует автомобиль"
    return "[URL]" % (WHATSAPP, quote(tekst, safe=""))


