def _schet_mashin(n, ukr=False):
    if ukr:
        slovo = "автомобіль" if n % 10 == 1 and n % 100 != 11 else (
            "автомобілі" if n % 10 in (2, 3, 4) and n % 100 not in (12, 13, 14)
            else "автомобілів")
    else:
        slovo = "автомобиль" if n % 10 == 1 and n % 100 != 11 else (
            "автомобиля" if n % 10 in (2, 3, 4) and n % 100 not in (12, 13, 14)
            else "автомобилей")
    return "%d %s" % (n, slovo)


