    c.append("<div class=\"wrap\">")
    c.append("<div class=\"h2\">%s</div>"
             % t("Автомобили в наличии и в пути", "Автомобілі в наявності та в дорозі"))
    c.append("<div class=\"sub\">%s</div>"
             % t("%s · цены под ключ в Киеве" % _schet_mashin(len(spisok)),
                 "%s · ціни під ключ у Києві" % _schet_mashin(len(spisok), True)))

    c.append("<div class=\"chipy\">")
    for klyuch, imya, nomer_etapa in FILTRY:
        skolko = len(spisok) if klyuch == "all" else len(
            [m for m in spisok if etap(m) == nomer_etapa])
        c.append("<a class=\"chip%s\" href=\"?f=%s\" data-f=\"%s\">%s <b>%d</b></a>"
                 % (" on" if klyuch == "all" else "", klyuch, klyuch,
                    t(imya[0], imya[1]), skolko))
