        klyuch = {4: "kiev", 3: "gruzia", 2: "more", 1: "korea"}[nomer_etapa]
        media = [t("%d фото" % len(foto), "%d фото" % len(foto))]
        if video_po_nomeru.get(nom):
            media.append(t("видео", "відео"))
        c.append("<a class=\"kat\" href=\"%s.html\" data-etap=\"%s\">" % (ekran(nom), klyuch))
        if foto:
            c.append("<img src=\"%s\" alt=\"%s\" loading=\"lazy\">"
                     % (ekran(foto[0]), ekran(nazvanie(m))))
        c.append("<div class=\"pr\">")
        c.append("<span class=\"pill\" style=\"border-color:%s;color:%s\">📍 %s</span>"
                 % (cvet, cvet, t(ETAP_KOROTKO[nomer_etapa][0],
