        c.append("<h3>%s</h3>" % ekran(nazvanie(m)))
        c.append("<div class=\"cn\">%s</div>" % ekran(dengi(m.get("price_uah"))))
        c.append("<div class=\"mt\">%s · %s</div>"
                 % (ekran(nom), " · ".join(media)))
        c.append("<div class=\"str\">→</div>")
        c.append("</div></a>")

    c.append("<div class=\"krt zol\" style=\"margin-top:16px\">")
    c.append("<div style=\"display:flex;gap:12px;align-items:center\">"
             "<div class=\"globus\">🔎</div><div style=\"font-size:16px;"
             "font-weight:700\">%s</div></div>"
             % t("Не нашли подходящий автомобиль?", "Не знайшли потрібне авто?"))
    c.append("<a class=\"knp zol\" href=\"podbor.html\">%s</a>"
             % t("Подобрать авто под заказ", "Підібрати авто на замовлення"))
    c.append("</div>")
    c.append(na_glavnuyu())
    c.append(kontakty_stroka())
    c.append(ftr())
    c.append("</div>")
    c.append("""<script>
(function(){var p=new URLSearchParams(location.search),f=p.get('f')||'all';
 var ch=document.querySelectorAll('.chip');
 for(var i=0;i<ch.length;i++){
  if(ch[i].getAttribute('data-f')===f){ch[i].classList.add('on')}
  else{ch[i].classList.remove('on')}}
 var k=document.querySelectorAll('.kat');
 for(var j=0;j<k.length;j++){
  k[j].style.display=(f==='all'||k[j].getAttribute('data-etap')===f)?'':'none'}
})();
</script>""")
    c.append(hvost())
    return "".join(c)


