def _js_str(z):
    z = "" if z is None else str(z)
    z = z.replace("\\", "\\\\").replace("'", "\\'")
    z = z.replace("&", "&amp;").replace('"', "&quot;")
    return "'" + z.replace("<", "&lt;").replace(">", "&gt;") + "'"


def _url(z):
    try:
        from urllib.parse import quote
        return quote(z, safe="")
    except Exception:
        return z


def blok_share(zag, tekst, adres):
    pok = "document.getElementById('mnu').style.display='flex';"
    nzh = ("var d={title:%s,text:%s,url:%s};try{if(navigator.share)"
           "{navigator.share(d).catch(function(){%s});}else{%s}}catch(e){%s}"
           % (_js_str(zag), _js_str(tekst), _js_str(adres), pok, pok, pok))
    zkr = "document.getElementById('mnu').style.display='none';"
    kop = ("var p=document.createElement('textarea');p.value=%s;"
           "p.setAttribute('readonly','');p.style.position='absolute';"
           "p.style.left='-9999px';document.body.appendChild(p);p.select();"
           "try{document.execCommand('copy');}catch(e){}"
           "if(navigator.clipboard&&navigator.clipboard.writeText)"
           "{try{navigator.clipboard.writeText(%s);}catch(e){}}"
           "document.body.removeChild(p);%s"
           "var w=document.getElementById('tst');w.style.display='block';"
           "setTimeout(function(){w.style.display='none';},2200);"
           % (_js_str(adres), _js_str(adres), zkr))
    tg = "[URL]" % (_url(adres), _url(tekst))
    wa = "[URL]" % _url(tekst + " " + adres)
    return "".join([
        "<button type=\"button\" class=\"shr\" aria-label=\"Поделиться\" "
        "onclick=\"%s\">%s</button>" % (nzh, ZNACHOK_SHARE),
        "<div class=\"mnu\" id=\"mnu\" onclick=\"if(event.target===this){%s}\">"
        "<div class=\"ok\">" % zkr,
        "<div style=\"text-align:center;color:var(--seryj);font-size:13px;"
        "margin-bottom:6px\">%s</div>"
        % t("Поделиться автомобилем", "Поділитися автомобілем"),
        "<a class=\"knp\" href=\"%s\" target=\"_blank\" rel=\"noopener\">Telegram</a>" % tg,
        "<a class=\"knp\" href=\"%s\" target=\"_blank\" rel=\"noopener\">WhatsApp</a>" % wa,
        "<button type=\"button\" class=\"knp\" onclick=\"%s\">%s</button>"
        % (kop, t("Копировать ссылку", "Копіювати посилання")),
        "<button type=\"button\" class=\"knp\" onclick=\"%s\">%s</button>"
        % (zkr, t("Закрыть", "Закрити")),
        "</div></div>",
        "<div class=\"tst\" id=\"tst\">%s</div>"
        % t("Ссылка скопирована", "Посилання скопійовано")])


